style.hiddenContent:
/* Preview frame shared by every view (from Lunch and Learn Simple's simple.css).
   Nothing in here is part of any demo. */
:root {
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: clamp(15px, 0.55vw + 9px, 21px);
  color: #1c1b22;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
}

:focus-visible {
  outline: 3px solid #1f6feb;
  outline-offset: 2px;
}

/* The demo area fills the preview. */
.stage {
  position: relative;
  height: 100vh;
  overflow: hidden;
  background: #fff;
}

/* Note shown by unsupported.js when the browser lacks the feature. */
.unsupported {
  position: absolute;
  left: 0.8rem;
  bottom: 0.8rem;
  z-index: 100;
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  max-width: min(26rem, calc(100% - 1.6rem));
  margin: 0;
  padding: 0.35rem 0.75rem;
  font-size: 0.72rem;
  line-height: 1.4;
  color: #b42318;
  background: rgb(253 233 230 / 0.95);
  border: 1px solid #f1b8b0;
  border-radius: 0.6rem;
  pointer-events: none;
}

.unsupported::before {
  content: '';
  flex: none;
  width: 0.45rem;
  height: 0.45rem;
  background: #e5372b;
  border-radius: 50%;
}

.unsupported b {
  color: #8f1d14;
}

/* Looks only, shared by before and after. No positioning logic here. */

/* The scrollable area fills the preview; its content is much taller. */
.scroller {
  position: absolute;
  inset: 0;
  overflow: auto;
}

.content {
  position: relative;
  height: 280%;
  background: #fbfaff radial-gradient(circle at 1px 1px, #dcd8f2 1px, transparent 1.5px) 0 0 / 24px 24px;
}

/* Starts in the middle of the visible part (the content is 280% of the preview height). */
.button {
  position: absolute;
  left: calc(50% - 3.5em);
  top: 20%;
  padding: 0.75rem 1.2rem;
  font: inherit;
  font-weight: 700;
  color: #fff;
  background: linear-gradient(135deg, #e0532f, #c13b64);
  border: 0;
  border-radius: 0.9rem;
  box-shadow: 0 10px 24px -10px rgb(193 59 100 / 0.8);
  cursor: grab;
  touch-action: none;
  user-select: none;
  /* An absolute box near the right edge would shrink and wrap "Drag me" otherwise */
  white-space: nowrap;
}

.tooltip {
  z-index: 1;
  width: 16rem;
  margin: 0;
  padding: 0.9rem 1.1rem;
  color: #f4f2fa;
  background: #1f1d2b;
  border-radius: 0.9rem;
  box-shadow: 0 18px 40px -18px rgb(20 18 40 / 0.7);
}

.tooltip strong {
  display: block;
  margin-bottom: 0.2rem;
}

.tooltip span {
  color: #c9c5dc;
  font-size: 0.9rem;
}

script.hiddenContent:
/*
  Demo helper, the same on both pages and not part of the comparison:
  drag the button (or move it with the arrow keys) anywhere in the scrollable
  area. It moves the button only, and fires a "move" event on it.
*/
(function () {
  var content = document.querySelector('.content');
  var button = document.querySelector('.button');
  var grab = null;

  function moveTo(left, top) {
    var maxX = content.clientWidth - button.offsetWidth;
    var maxY = content.clientHeight - button.offsetHeight;
    button.style.left = Math.round(Math.max(0, Math.min(maxX, left))) + 'px';
    button.style.top = Math.round(Math.max(0, Math.min(maxY, top))) + 'px';
    button.dispatchEvent(new Event('move'));
  }

  button.addEventListener('pointerdown', function (e) {
    var r = button.getBoundingClientRect();
    grab = { dx: e.clientX - r.left, dy: e.clientY - r.top };
    button.setPointerCapture(e.pointerId);
  });
  button.addEventListener('pointermove', function (e) {
    if (!grab) return;
    // The content's rectangle already includes the scroll offset.
    var c = content.getBoundingClientRect();
    moveTo(e.clientX - c.left - grab.dx, e.clientY - c.top - grab.dy);
  });
  button.addEventListener('pointerup', function () {
    grab = null;
  });
  button.addEventListener('keydown', function (e) {
    var step = e.shiftKey ? 60 : 15;
    var d = { ArrowLeft: [-step, 0], ArrowRight: [step, 0], ArrowUp: [0, -step], ArrowDown: [0, step] }[e.key];
    if (!d) return;
    e.preventDefault();
    moveTo(button.offsetLeft + d[0], button.offsetTop + d[1]);
  });

  // The start position is set in look.css: in LiveCodes the preview can still be 0×0 when
  // this runs, and placing the button from here would put it in the corner.
})();

// A small note in the preview when the browser lacks the feature a modern view shows.
// `support` comes from feature.js: { css: 'display: grid-lanes' } or { api: 'popover' }.
function showUnsupported(support) {
  const API = { popover: () => 'showPopover' in HTMLElement.prototype };
  const ok = support.api ? API[support.api]() : CSS.supports(support.css);
  if (ok) return;
  const note = document.createElement('p');
  note.className = 'unsupported';
  const name = document.createElement('b');
  name.textContent = support.feature;
  const text = document.createElement('span');
  text.append(name, ' isn’t supported in this browser.' + (support.hint ? ` ${support.hint}` : ''));
  note.append(text);
  (document.querySelector('.stage') ?? document.body).prepend(note);
}

